diff --git a/default.properties b/default.properties
index 33bf35487..0a90c9386 100644
--- a/default.properties
+++ b/default.properties
@@ -70,12 +70,12 @@ compile.optimize = true
 # In particular, if you use JDK 1.4+ the generated classes will not be usable
 # for a 1.1 Java VM unless you explicitly set this attribute to the value 1.1 
 # (which is the default value for JDK 1.1 to 1.3).
-compile.target = 1.6
+compile.target = 1.8

 # Specifies the source version for the Java compiler.
 # Corresponds to the source attribute for the ant javac task. 
 # Valid values are 1.3, 1.4, 1.5. 
-compile.source = 1.6
+compile.source = 1.8

 # Specifies the source encoding.
 compile.encoding = ISO-8859-1
diff --git a/src/main/java/org/apache/commons/lang3/math/NumberUtils.java b/src/main/java/org/apache/commons/lang3/math/NumberUtils.java
index 1e6ccdc02..36e1921c1 100644
--- a/src/main/java/org/apache/commons/lang3/math/NumberUtils.java
+++ b/src/main/java/org/apache/commons/lang3/math/NumberUtils.java
@@ -464,11 +464,19 @@ public class NumberUtils {
             }
         }
         if (pfxLen > 0) { // we have a hex number
-            final int hexDigits = str.length() - pfxLen;
-            if (hexDigits > 16) { // too many for Long
+            final String hexStr = str.substring(pfxLen);
+            // Strip leading zeros to count significant hex digits
+            int firstNonZero = 0;
+            while (firstNonZero < hexStr.length() - 1 && hexStr.charAt(firstNonZero) == '0') {
+                firstNonZero++;
+            }
+            final int sigDigits = hexStr.length() - firstNonZero;
+            final char firstSigChar = hexStr.charAt(firstNonZero);
+            // A sigDigit of N means the value needs N*4 bits; first digit > '7' means top bit is set
+            if (sigDigits > 16 || (sigDigits == 16 && firstSigChar > '7')) {
                 return createBigInteger(str);
             }
-            if (hexDigits > 8) { // too many for an int
+            if (sigDigits > 8 || (sigDigits == 8 && firstSigChar > '7')) {
                 return createLong(str);
             }
             return createInteger(str);

